<?php
require __DIR__ . '/bootstrap.php';
function h($s) { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function valid_url($url, $hosts) { $p=parse_url((string)$url); return is_array($p) && ($p['scheme']??'')==='https' && in_array($p['host']??'', $hosts, true) ? (string)$url : ''; }
$groups=[]; $error=false;
try { foreach (all_works(db()) as $work) { if ($work['status']!=='販売中') continue; $url=valid_url($work['storeUrl'], ['store.line.me']); if (!$url) continue; $work['storeUrl']=$url; $work['image']=valid_url($work['image'], ['stickershop.line-scdn.net','stickershop.line.me','shop.line-scdn.net']); $series=trim($work['series']) ?: 'その他の作品'; if ($series === 'その他の作品') { $title=(string)$work['title']; if (preg_match('/花あかり|ほたる|雪もち|みのり/u', $title)) $series='子狐四つ子'; elseif (mb_strpos($title, 'ラムネ') !== false) $series='もちぷるメンダコ'; } $groups[$series][]=$work; } }
catch (Throwable $e) { error_log('Stamp gallery: '.$e->getMessage()); http_response_code(503); $error=true; }
uksort($groups, function($a,$b) { if ($a==='その他の作品') return 1; if ($b==='その他の作品') return -1; return strnatcasecmp($a,$b); });
$total=array_sum(array_map('count',$groups));
?>
<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="アイアイのLINEスタンプ・絵文字・着せかえをキャラクター別に紹介。ペンキューやウッポーなどの作品を探せます。"><title>キャラクター別 LINEスタンプ・絵文字・着せかえ作品集 | いじぽ</title>
<style>
:root{--ink:#26343b;--muted:#5d6d72;--accent:#126d70;--line:#dce7e6}*{box-sizing:border-box}body{margin:0;background:#f5f9f8;color:var(--ink);font-family:"Yu Gothic",Meiryo,sans-serif;line-height:1.65}a{color:var(--accent)}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #e79d29;outline-offset:3px}.wrap{max-width:1160px;margin:auto;padding:0 20px}.hero{background:linear-gradient(120deg,#d7f5eb,#fff1db);padding:25px 0 48px}.hero h1{font-size:clamp(1.9rem,5vw,3rem);line-height:1.25;margin:34px 0 12px}.hero p{max-width:660px;margin:0}.stats{font-weight:bold;margin-top:18px}.nav{display:flex;gap:18px;flex-wrap:wrap}.controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:22px 0}.search{flex:1 1 230px;max-width:420px;padding:11px;border:1px solid #a7bcb9;border-radius:10px;font:inherit}.filters{display:flex;gap:8px;flex-wrap:wrap}button{border:1px solid #a7bcb9;border-radius:99px;padding:8px 14px;background:white;color:var(--ink);font:inherit;cursor:pointer}button[aria-pressed=true]{background:var(--accent);border-color:var(--accent);color:white}.jump{display:flex;gap:8px;overflow-x:auto;padding-bottom:18px}.jump a{white-space:nowrap;background:white;border:1px solid var(--line);border-radius:99px;padding:6px 12px;text-decoration:none}.group{padding:10px 0 26px;scroll-margin-top:20px}.group h2{font-size:1.4rem;margin:8px 0 0}.count{color:var(--muted);margin:0 0 14px;font-size:.9rem}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 3px 12px #2342}.thumb{aspect-ratio:1.2;display:grid;place-items:center;background:#edf7f3;padding:14px}.thumb img{max-width:100%;max-height:100%;object-fit:contain}.body{padding:14px;display:flex;flex-direction:column;gap:8px;flex:1}.kind{align-self:start;background:#e5f3ef;border-radius:99px;color:#146168;padding:2px 9px;font-size:.8rem}.body h3{font-size:1rem;line-height:1.45;margin:0}.desc{font-size:.85rem;color:var(--muted);margin:0;flex:1;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.store{display:block;text-align:center;color:white;background:var(--accent);padding:9px;text-decoration:none;border-radius:9px;font-weight:bold;margin-top:auto}.store:hover{background:#0c5356}.message{padding:28px 0;color:var(--muted)}footer{border-top:1px solid var(--line);padding:28px 0;margin-top:24px;color:var(--muted);font-size:.88rem}[hidden]{display:none!important}</style></head><body>
<header class="hero"><div class="wrap"><nav class="nav" aria-label="サイト内リンク"><a href="/">いじぽ トップ</a><a href="/wordpress/">読みもの</a></nav><h1>キャラクター別<br>LINEスタンプ・絵文字・着せかえ作品集</h1><p>お気に入りのキャラクターから作品を探せます。気になる作品はLINE STOREで詳細をご覧ください。着せかえも一緒に探せます。</p><div class="stats"><?= count($groups) ?> シリーズ・<?= $total ?> 作品</div></div></header>
<main class="wrap">
<?php if ($error): ?><p class="message">ただいま作品を読み込めません。時間をおいて再度お試しください。</p>
<?php elseif (!$groups): ?><p class="message">公開中の作品はまだありません。</p>
<?php else: ?>
<div class="controls"><label for="search">作品を探す</label><input id="search" class="search" type="search" placeholder="キャラクター名・作品名で検索"><div class="filters" role="group" aria-label="作品の種類"><button type="button" data-type="all" aria-pressed="true">すべて</button><button type="button" data-type="スタンプ" aria-pressed="false">スタンプ</button><button type="button" data-type="絵文字" aria-pressed="false">絵文字</button><button type="button" data-type="着せかえ" aria-pressed="false">着せかえ</button></div></div>
<nav class="jump" aria-label="キャラクター一覧"><?php $i=0; foreach($groups as $series=>$items): ?><a href="#series-<?= $i++ ?>"><?= h($series) ?></a><?php endforeach; ?></nav><p id="result" role="status" aria-live="polite"></p>
<?php $i=0; foreach($groups as $series=>$items): ?><section class="group" id="series-<?= $i++ ?>"><h2><?= h($series) ?></h2><?php if($series==='子狐四つ子'): ?><p class="count">花あかり・ほたる・雪もち・みのり</p><?php elseif($series==='もちぷるメンダコ'): ?><p class="count">ラムネちゃんの作品もこちら</p><?php endif; ?><p class="count"><?= count($items) ?> 作品</p><div class="grid">
<?php foreach($items as $work): ?><article class="card" data-type="<?= h($work['type']) ?>" data-search="<?= h($series.' '.($series==='子狐四つ子' ? '花あかり ほたる 雪もち みのり ' : ($series==='もちぷるメンダコ' ? 'ラムネ ラムネちゃん ' : '')).$work['title'].' '.$work['type']) ?>"><div class="thumb"><?php if($work['image']): ?><img src="<?= h($work['image']) ?>" alt="<?= h($work['title']) ?>の画像" loading="lazy"><?php else: ?><span aria-hidden="true">✦</span><?php endif; ?></div><div class="body"><span class="kind"><?= h($work['type']) ?></span><h3><?= h($work['title']) ?></h3><?php if(trim($work['description'])!==''): ?><p class="desc"><?= h($work['description']) ?></p><?php endif; ?><a class="store" href="<?= h($work['storeUrl']) ?>" target="_blank" rel="noopener noreferrer">LINE STOREで見る ↗</a></div></article><?php endforeach; ?>
</div></section><?php endforeach; ?><p class="message" id="no-results" hidden>該当する作品が見つかりませんでした。</p><?php endif; ?></main><footer><div class="wrap">掲載作品は管理データに登録された販売中の作品です。<br><a href="/">いじぽ トップへ戻る</a></div></footer>
<script>(()=>{const search=document.getElementById('search');if(!search)return;const cards=[...document.querySelectorAll('.card')],groups=[...document.querySelectorAll('.group')],buttons=[...document.querySelectorAll('.filters button')];let type='all';function update(){const q=search.value.trim().toLocaleLowerCase();let visible=0;for(const card of cards){const show=(type==='all'||card.dataset.type===type)&&(card.dataset.search||'').toLocaleLowerCase().includes(q);card.hidden=!show;if(show)visible++}for(const group of groups)group.hidden=!group.querySelector('.card:not([hidden])');document.getElementById('result').textContent=visible+' 作品を表示';document.getElementById('no-results').hidden=visible!==0}search.addEventListener('input',update);for(const button of buttons)button.addEventListener('click',()=>{type=button.dataset.type;for(const b of buttons)b.setAttribute('aria-pressed',String(b===button));update()});update()})();</script></body></html>
